package vn.svframe.lively.integration;
import vn.svframe.lively.api.EconomyBridge;import java.lang.reflect.Field;import java.lang.reflect.Method;import java.math.BigDecimal;import java.util.UUID;
/** Optional bridge verified against BEconomy 1.5 EconomyAPI signatures. */
final class BEconomyBridge implements EconomyBridge{private final Object singleton;private final Method initialized,getApi;private BEconomyBridge(Object s,Method i,Method g){singleton=s;initialized=i;getApi=g;}static EconomyBridge create(){try{Class<?>c=Class.forName("org.krripe.beconomy.api.BEconomy");Field f=c.getField("INSTANCE");Object s=f.get(null);return new BEconomyBridge(s,c.getMethod("isInitialized"),c.getMethod("getAPI"));}catch(ReflectiveOperationException e){return EconomyBridge.unavailable();}}@Override public boolean available(){try{return Boolean.TRUE.equals(initialized.invoke(singleton));}catch(ReflectiveOperationException e){return false;}}private Object api(){try{return getApi.invoke(singleton);}catch(ReflectiveOperationException e){throw new IllegalStateException("BEconomy API unavailable",e);}}@Override public BigDecimal balance(UUID actor,String currency){try{Object a=api();return(BigDecimal)a.getClass().getMethod("getBalance",UUID.class,String.class).invoke(a,actor,currency);}catch(ReflectiveOperationException e){throw new IllegalStateException("BEconomy balance failed",e);}}@Override public void deposit(UUID actor,BigDecimal amount,String currency){validate(amount);try{Object a=api();a.getClass().getMethod("addBalance",UUID.class,BigDecimal.class,String.class).invoke(a,actor,amount,currency);}catch(ReflectiveOperationException e){throw new IllegalStateException("BEconomy deposit failed",e);}}@Override public boolean withdraw(UUID actor,BigDecimal amount,String currency){validate(amount);try{Object a=api();return Boolean.TRUE.equals(a.getClass().getMethod("subtractBalance",UUID.class,BigDecimal.class,String.class).invoke(a,actor,amount,currency));}catch(ReflectiveOperationException e){throw new IllegalStateException("BEconomy withdraw failed",e);}}@Override public boolean transfer(UUID from,UUID to,BigDecimal amount,String currency){validate(amount);try{Object a=api();return Boolean.TRUE.equals(a.getClass().getMethod("transfer",UUID.class,UUID.class,BigDecimal.class,String.class).invoke(a,from,to,amount,currency));}catch(ReflectiveOperationException e){throw new IllegalStateException("BEconomy transfer failed",e);}}private static void validate(BigDecimal a){if(a==null||a.signum()<0)throw new IllegalArgumentException("invalid economy amount");}}
